"use client";
import { useState } from "react";
import { motion } from "motion/react";
import {
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface HoverableListItem extends GalleryInternalItem {}
export interface HoverableListProps extends GalleryInternalProps {
  items: readonly HoverableListItem[];
  fill?: string;
  activeColor?: string;
  duration?: number;
  curvature?: number;
}
export function HoverableList(props: HoverableListProps) {
  const {
    items,
    fill = "#ff4b00",
    activeColor = "#111",
    duration = 0.65,
    curvature = 40,
    height = 640,
    label = "Collections",
    className = "",
    style,
    onSelect,
    renderCaption,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  const [hovered, setHovered] = useState<number | null>(null);
  const [directions, setDirections] = useState<Record<number, number>>({});
  const activate = (i: number) => {
    choose(i);
    setHovered(i);
  };
  return (
    <div
      ref={env.ref}
      className={`z-ag z-ag-list ${className}`}
      data-gallery="hoverable-list"
      data-index={current}
      role="region"
      aria-label={label}
      onPointerLeave={() => setHovered(null)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setHovered(null);
      }}
      style={galleryStyle(height, style)}
    >
      <GalleryInternalStyles />
      {items.map((item, i) => {
        const active = hovered === i;
        const bottom = directions[i] === 1;
        const curved = bottom
          ? `M 0 ${105 + curvature} Q 50 105 100 ${105 + curvature} L 100 200 L 0 200 Z`
          : `M 0 ${-5 - curvature} Q 50 -5 100 ${-5 - curvature} L 100 -100 L 0 -100 Z`;
        const full = bottom
          ? "M 0 -5 Q 50 -5 100 -5 L 100 200 L 0 200 Z"
          : "M 0 105 Q 50 105 100 105 L 100 -100 L 0 -100 Z";
        return (
          <button
            type="button"
            key={item.id}
            className="z-ag-row"
            data-gallery-card={i}
            data-active={active}
            data-direction={bottom ? "bottom" : "top"}
            onPointerEnter={(e) => {
              if (e.pointerType === "touch") return;
              const b = e.currentTarget.getBoundingClientRect();
              setDirections((d) => ({ ...d, [i]: e.clientY > b.top + b.height / 2 ? 1 : -1 }));
              activate(i);
            }}
            onPointerLeave={(e) => {
              const b = e.currentTarget.getBoundingClientRect();
              setDirections((d) => ({ ...d, [i]: e.clientY > b.top + b.height / 2 ? 1 : -1 }));
              setHovered(null);
            }}
            onFocus={() => activate(i)}
            onClick={() => {
              activate(i);
              onSelect?.(item, i);
            }}
            style={{ color: active ? activeColor : undefined }}
          >
            <svg
              viewBox="0 0 100 100"
              preserveAspectRatio="none"
              aria-hidden="true"
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
            >
              <motion.path
                className="z-ag-list-wave"
                initial={false}
                animate={{ d: active ? full : curved }}
                transition={{ duration: env.reduced ? 0 : duration, ease: [0.22, 1, 0.36, 1] }}
                fill={fill}
              />
            </svg>
            <span className="z-ag-row-label">{renderCaption?.(item, i) ?? item.title}</span>
          </button>
        );
      })}
    </div>
  );
}
